package com.smartelder.api.tenant.portal;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.smartelder.core.api.access.TenantAccessContext;
import com.smartelder.api.tenant.auth.TenantStaffAuthException;
import java.time.Instant;
import java.sql.Timestamp;
import java.util.*;
import java.io.*;
import javax.imageio.ImageIO;
import org.springframework.jdbc.core.simple.JdbcClient;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
@Service
public class PublicSiteService {
 private final JdbcClient jdbc;private final ObjectMapper mapper;
 public PublicSiteService(JdbcClient jdbc,ObjectMapper mapper){this.jdbc=jdbc;this.mapper=mapper;}
 private void permit(TenantAccessContext a,String p){if(!a.permissionCodes().contains(p))throw new TenantStaffAuthException(403,"PERMISSION_DENIED","无权操作首页内容");}
 private String key(String target,TenantAccessContext a){if("brand".equals(target)){if(!"HQ".equals(a.staffType()))throw new TenantStaffAuthException(403,"PERMISSION_DENIED","仅总部可管理企业品牌");return target;}Long id=jdbc.sql("SELECT id FROM core_store WHERE public_id=:id").param("id",target).query(Long.class).optional().orElseThrow(()->new IllegalArgumentException("门店不存在"));if(!"ALL".equals(a.dataScope().type())&&!a.dataScope().storeIds().contains(id))throw new TenantStaffAuthException(403,"DATA_SCOPE_DENIED","门店不在管理范围内");return "store:"+target;}
 private Content empty(){return new Content("","","","","","","","/images/enterprise-residence.png",List.of());}
 private Row row(String key){return jdbc.sql("SELECT draft_json,submitted_json,published_json,review_status,review_note FROM site_public_content WHERE target_key=:key").param("key",key).query((rs,n)->new Row(rs.getString(1),rs.getString(2),rs.getString(3),rs.getString(4),rs.getString(5))).optional().orElse(null);}
 private Content parse(String s){if(s==null)return null;try{return mapper.readValue(s,Content.class);}catch(Exception e){throw new IllegalStateException("首页内容读取失败");}}
 private String json(Content c){try{return mapper.writeValueAsString(c);}catch(Exception e){throw new IllegalArgumentException("首页内容格式无效");}}
 public Editor editor(String target,TenantAccessContext a){permit(a,"core.site.view");Row r=row(key(target,a));return r==null?new Editor(empty(),null,null,"DRAFT",null,""):new Editor(parse(r.draft()),parse(r.submitted()),parse(r.published()),r.status(),r.note(),token(r.submitted()));}
 private String text(String s,int max){if(s==null)return "";if(s.length()>max)throw new IllegalArgumentException("内容超过长度限制");return s.trim();}
 private String image(String value){if(value==null||value.isBlank())return "";if(Set.of("/images/enterprise-residence.png","/images/enterprise-welcome.png","/images/enterprise-lounge.png","/images/senior-residence.png").contains(value))return value;if(value.length()>2800000||!(value.startsWith("data:image/jpeg;base64,")||value.startsWith("data:image/png;base64,")))throw new IllegalArgumentException("图片仅支持 2MB 内 JPG/PNG");try{byte[] bytes=Base64.getDecoder().decode(value.substring(value.indexOf(',')+1));if(bytes.length>2097152)throw new IllegalArgumentException("图片超过2MB");try(var stream=ImageIO.createImageInputStream(new ByteArrayInputStream(bytes))){var readers=ImageIO.getImageReaders(stream);if(!readers.hasNext())throw new IllegalArgumentException("图片无效");var reader=readers.next();try{reader.setInput(stream);String f=reader.getFormatName();if(!f.equalsIgnoreCase("JPEG")&&!f.equalsIgnoreCase("PNG"))throw new IllegalArgumentException("图片格式无效");int w=reader.getWidth(0),h=reader.getHeight(0);if(w<1||h<1||w>4096||h>4096||(long)w*h>16000000)throw new IllegalArgumentException("图片尺寸过大");var source=reader.read(0);double scale=Math.min(1,1600.0/Math.max(w,h));var output=new java.awt.image.BufferedImage(Math.max(1,(int)(w*scale)),Math.max(1,(int)(h*scale)),java.awt.image.BufferedImage.TYPE_INT_RGB);var g=output.createGraphics();try{g.setColor(java.awt.Color.WHITE);g.fillRect(0,0,output.getWidth(),output.getHeight());g.drawImage(source,0,0,output.getWidth(),output.getHeight(),null);}finally{g.dispose();}var out=new ByteArrayOutputStream();ImageIO.write(output,"jpeg",out);return "data:image/jpeg;base64,"+Base64.getEncoder().encodeToString(out.toByteArray());}finally{reader.dispose();}}}catch(IOException e){throw new IllegalArgumentException("无法读取图片",e);}}
 private Content clean(Content c){if(c==null)throw new IllegalArgumentException("内容不能为空");var gallery=c.gallery()==null?List.<Photo>of():c.gallery();if(gallery.size()>6)throw new IllegalArgumentException("最多6张环境图片");return new Content(text(c.title(),100),text(c.subtitle(),200),text(c.introduction(),5000),text(c.philosophy(),1000),text(c.publicAddress(),500),text(c.publicPhone(),32),text(c.visitNote(),1000),image(c.heroImage()),gallery.stream().map(p->new Photo(image(p.url()),text(p.caption(),150))).toList());}
 private void audit(String key,String action,TenantAccessContext a){jdbc.sql("INSERT INTO audit_tenant_log(actor_staff_id,action,target_type,target_public_id,trace_id,details_json,created_at) VALUES(:actor,:action,'PUBLIC_SITE',:key,'site-content','{}',:now)").param("actor",a.staffId()).param("action",action).param("key",key.startsWith("store:")?key.substring(6):key).param("now",Timestamp.from(Instant.now())).update();}
 @Transactional public void save(String target,Content c,TenantAccessContext a){permit(a,"core.site.manage");String k=key(target,a),data=json(clean(c));if(row(k)==null){jdbc.sql("INSERT INTO site_public_content(target_key,draft_json,review_status,updated_at) VALUES(:key,:data,'DRAFT',:now)").param("key",k).param("data",data).param("now",Timestamp.from(Instant.now())).update();}else jdbc.sql("UPDATE site_public_content SET draft_json=:data,updated_at=:now WHERE target_key=:key").param("data",data).param("now",Timestamp.from(Instant.now())).param("key",k).update();audit(k,"SITE_DRAFT_SAVED",a);}
 @Transactional public void publish(String target,TenantAccessContext a){permit(a,"core.site.manage");String k=key(target,a);if(!"brand".equals(k)||!"HQ".equals(a.staffType()))throw new TenantStaffAuthException(403,"PERMISSION_DENIED","门店内容需要总部审核");requireTitle(k);jdbc.sql("UPDATE site_public_content SET published_json=draft_json,review_status='PUBLISHED',updated_at=:now WHERE target_key=:key").param("now",Timestamp.from(Instant.now())).param("key",k).update();audit(k,"BRAND_SITE_PUBLISHED",a);}
 private void requireTitle(String k){Row r=row(k);if(r==null||parse(r.draft()).title().isBlank()||parse(r.draft()).introduction().isBlank())throw new IllegalArgumentException("发布或提交前请填写标题与介绍");}
 @Transactional public void submit(String target,TenantAccessContext a){permit(a,"core.site.manage");String k=key(target,a);if("brand".equals(k))throw new IllegalArgumentException("品牌首页由总部直接发布");requireTitle(k);jdbc.sql("UPDATE site_public_content SET submitted_json=draft_json,review_status='PENDING',review_note=NULL,updated_at=:now WHERE target_key=:key").param("now",Timestamp.from(Instant.now())).param("key",k).update();audit(k,"STORE_SITE_SUBMITTED",a);}
 @Transactional public void review(String target,boolean approve,String note,String expectedToken,TenantAccessContext a){permit(a,"core.site.review");if(!"HQ".equals(a.staffType()))throw new TenantStaffAuthException(403,"PERMISSION_DENIED","仅总部可审核");String k=key(target,a);if("brand".equals(k))throw new IllegalArgumentException("品牌无需审核");String state=jdbc.sql("SELECT review_status FROM site_public_content WHERE target_key=:key FOR UPDATE").param("key",k).query(String.class).optional().orElse("");if(!"PENDING".equals(state))throw new IllegalStateException("内容不是待审核状态");if(expectedToken==null||!expectedToken.equals(token(row(k).submitted())))throw new IllegalStateException("送审内容已更新，请重新读取后审核");jdbc.sql(approve?"UPDATE site_public_content SET published_json=submitted_json,review_status='PUBLISHED',review_note=:note,updated_at=:now WHERE target_key=:key":"UPDATE site_public_content SET review_status='REJECTED',review_note=:note,updated_at=:now WHERE target_key=:key").param("note",text(note,500)).param("now",Timestamp.from(Instant.now())).param("key",k).update();audit(k,approve?"STORE_SITE_APPROVED":"STORE_SITE_REJECTED",a);}
 public Map<String,String> ownStore(TenantAccessContext a){permit(a,"core.site.view");if(!"STORE".equals(a.staffType())||a.homeStoreId()==null)throw new IllegalArgumentException("当前账号不是门店员工");return jdbc.sql("SELECT public_id,store_no,name FROM core_store WHERE id=:id").param("id",a.homeStoreId()).query((rs,n)->Map.of("publicId",rs.getString(1),"storeNo",rs.getString(2),"name",rs.getString(3))).single();}
 public PublicPage brand(){String name=jdbc.sql("SELECT name FROM core_enterprise ORDER BY id LIMIT 1").query(String.class).optional().orElse("企业品牌");Row r=row("brand");return new PublicPage(name,null,r==null?null:parse(r.published()),List.of());}
 public List<StoreCard> stores(){return jdbc.sql("SELECT public_id,store_no,name FROM core_store WHERE status='ACTIVE' ORDER BY store_no").query((rs,n)->{Row r=row("store:"+rs.getString(1));Content c=r==null?null:parse(r.published());return new StoreCard(rs.getString(2),rs.getString(3),c==null?"":c.publicAddress(),c==null?"":c.heroImage());}).list();}
 public PublicPage store(String no){var id=jdbc.sql("SELECT public_id,name FROM core_store WHERE store_no=:no AND status='ACTIVE'").param("no",no).query((rs,n)->new String[]{rs.getString(1),rs.getString(2)}).optional().orElseThrow(()->new IllegalArgumentException("门店暂未开放"));Row r=row("store:"+id[0]);return new PublicPage(id[1],no,r==null?null:parse(r.published()),List.of());}
 private String token(String value){if(value==null)return "";try{return java.util.HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-256").digest(value.getBytes(java.nio.charset.StandardCharsets.UTF_8)));}catch(java.security.NoSuchAlgorithmException e){throw new IllegalStateException(e);}}
 public record Photo(String url,String caption){}
 public record Content(String title,String subtitle,String introduction,String philosophy,String publicAddress,String publicPhone,String visitNote,String heroImage,List<Photo> gallery){}
 private record Row(String draft,String submitted,String published,String status,String note){}
 public record Editor(Content draft,Content submitted,Content published,String status,String reviewNote,String reviewToken){}
 public record PublicPage(String name,String storeNo,Content content,List<StoreCard> stores){}
 public record StoreCard(String storeNo,String name,String publicAddress,String heroImage){}
}
